-- Completa las localidades de Bogotá que todavía no tenían ningún hospedaje. Antes de esto
-- (ver 08-localidades-bogota.sql) solo 12 de las 20 localidades oficiales tenían datos:
-- Usaquén, Chapinero, Teusaquillo, Suba, Kennedy, Engativá, Fontibón, Bosa, La Candelaria,
-- Puente Aranda, Barrios Unidos, Rafael Uribe Uribe. Faltaban: Santa Fe, San Cristóbal,
-- Usme, Tunjuelito, Los Mártires, Antonio Nariño, Ciudad Bolívar y Sumapaz — sin datos ahí,
-- buscar/filtrar por esas localidades (o ver el mapa segmentado) siempre daba "sin
-- resultados", aunque son localidades válidas del Distrito.
--
-- Aplicar después de 28-preferencias-demo.sql:
--   psql "postgres://pethouse:pethouse@localhost:5432/pethouse" -f 29-mas-localidades.sql

-- Tres de los hospedajes nuevos quedan a nombre de anfitriones (Andrés, Valentina, Lucía)
-- que hasta ahora solo tenían hospedajes fuera de Bogotá (Medellín/Cali/Chía) y por eso
-- nunca habían llenado `preferencias_anfitrion` (ver 06-verificacion-anfitrion.sql y
-- 28-preferencias-demo.sql) — sin esto, sus hospedajes nuevos no aparecerían nunca en el
-- filtro real de especie (Perros/Gatos) de Buscar.
INSERT INTO preferencias_anfitrion (usuario_id, especies, modalidades, tamanos) VALUES
('00000000-0000-0000-0000-000000000003', ARRAY['perro','gato'], ARRAY['dias','horas'], ARRAY['pequeno','mediano','grande']),
('00000000-0000-0000-0000-000000000004', ARRAY['perro','gato'], ARRAY['dias'],         ARRAY['pequeno','mediano','grande']),
('00000000-0000-0000-0000-000000000006', ARRAY['perro','gato'], ARRAY['dias','horas'], ARRAY['pequeno','mediano','grande'])
ON CONFLICT (usuario_id) DO NOTHING;

