('20000000-0000-0000-0000-000000000029', '00000000-0000-0000-0000-000000000004', 'domicilio', 'Pet sitter en tu casa — San Cristóbal', 'Valentina cuida a tu mascota en tu propia casa en San Cristóbal, con visitas programadas o estancia parcial. Perfecto para mascotas que prefieren no salir de su territorio.', 'Bogotá', '20 de Julio', 'San Cristóbal', ST_SetSRID(ST_MakePoint(-74.083, 4.557), 4326), 12000, 50000, 'individual', 2, 4.7, 18, false, '{Visitas 2 veces al día,Paseos mañana y tarde,Reporte por WhatsApp,Flexibilidad de horarios}', '{Vacunas al día,Zona San Cristóbal y aledaños,Indicar dieta y medicamentos}', '{/semilla/a1.jpg,/semilla/a2.jpg}', TRUE),
('20000000-0000-0000-0000-000000000030', '00000000-0000-0000-0000-000000000002', 'guarderia', 'Guardería Usme Sur', 'Guardería boutique en Usme con grupos reducidos de juego y patio amplio. Reporte fotográfico diario y personal certificado en primeros auxilios caninos.', 'Bogotá', 'Usme Centro', 'Usme', ST_SetSRID(ST_MakePoint(-74.126, 4.487), 4326), NULL, 42000, 'compartida', 6, 4.5, 12, false, '{Juego supervisado,Paseos diarios,Alimentación incluida,Reporte fotográfico diario,Patio amplio}', '{Vacunas al día obligatorias,Mascotas mayores de 4 meses,Desparasitación reciente}', '{/semilla/g1.jpg,/semilla/g2.jpg}', TRUE),
('20000000-0000-0000-0000-000000000031', '00000000-0000-0000-0000-000000000007', 'domicilio', 'Cuidadora a domicilio — Tunjuelito', 'Jorge se desplaza hasta Tunjuelito para cuidar a tu mascota en casa, con amplia experiencia en mascotas senior y administración de medicamentos.', 'Bogotá', 'Tunjuelito Centro', 'Tunjuelito', ST_SetSRID(ST_MakePoint(-74.132, 4.572), 4326), 12000, 53000, 'individual', 2, 4.6, 14, false, '{Visitas mañana y tarde,Reporte fotográfico diario,Alimentación y medicamentos,Experiencia con mascotas senior}', '{Vacunas al día,Zona Tunjuelito y alrededores,Entrevista previa gratuita}', '{/semilla/a2.jpg,/semilla/a1.jpg}', TRUE),
('20000000-0000-0000-0000-000000000032', '00000000-0000-0000-0000-000000000003', 'apartamento', 'Apartamento Pet Friendly — Los Mártires', 'Apartamento acogedor cerca al centro, en Los Mártires, con anfitrión presente todo el día. Máximo 2 huéspedes para garantizar atención personalizada.', 'Bogotá', 'Ricaurte', 'Los Mártires', ST_SetSRID(ST_MakePoint(-74.093, 4.604), 4326), NULL, 48000, 'individual', 2, 4.5, 16, false, '{Anfitrión en casa,Parques cercanos,Cama y juguetes incluidos,Cámaras en sala,Apto para gatos}', '{Vacunas al día,Mascotas menores de 15 kg,Reportar alergias o medicamentos}', '{/semilla/a1.jpg,/semilla/a2.jpg}', TRUE),
('20000000-0000-0000-0000-000000000033', '00000000-0000-0000-0000-000000000005', 'veterinaria', 'VetStay Antonio Nariño', 'Hospedaje clínico en Antonio Nariño con supervisión médica permanente, ideal para mascotas con condiciones especiales o en tratamiento. Chequeo diario incluido.', 'Bogotá', 'Restrepo', 'Antonio Nariño', ST_SetSRID(ST_MakePoint(-74.106, 4.583), 4326), NULL, 78000, 'individual', 4, 4.8, 27, false, '{Supervisión médica 24/7,Administración de medicamentos,Chequeo diario,Hospitalización cómoda,Urgencias incluidas}', '{Historia clínica al ingreso,Vacunas al día,Mascotas con condición médica bienvenidas}', '{/semilla/v1.jpg,/semilla/v2.jpg}', TRUE),
