('20000000-0000-0000-0000-000000000035', '00000000-0000-0000-0000-000000000006', 'campestre', 'Finca Páramo de Sumapaz', 'Finca campestre en la zona rural de Sumapaz, rodeada de páramo y aire libre — ideal para perros que aman correr y explorar espacios abiertos bajo supervisión constante. Alojamiento con chimenea para el clima frío de la zona.', 'Bogotá', 'Nazareth', 'Sumapaz', ST_SetSRID(ST_MakePoint(-74.208, 4.263), 4326), NULL, 95000, 'compartida', 6, 4.8, 9, false, '{Zona rural de páramo,Senderos para caminatas,Chimenea para el frío,Cámaras en zonas comunes,Fogata nocturna}', '{Vacunas al día,Perros con buen comportamiento,Correa durante transporte}', '{/semilla/c1.jpg,/semilla/c2.jpg}', TRUE);
